<?php namespace App\Services; use App\Models\Invoice; use App\Models\Product; use App\Models\Sale; use Illuminate\Validation\ValidationException; use Illuminate\Support\Facades\DB; class RecordSaleService { public function record(array $data,?int $userId):Sale{return DB::transaction(function()use($data,$userId){$subtotal='0.00';$lines=[];foreach($data['items'] as $item){$product=Product::lockForUpdate()->findOrFail($item['product_id']);if(bccomp($product->stock_quantity,(string)$item['quantity'],3)<0)throw ValidationException::withMessages(['items'=>"Insufficient stock for {$product->name}. Available: {$product->stock_quantity} {$product->unit}."]);$line=Money::mul((string)$item['quantity'],(string)$item['selling_price']);$subtotal=Money::add($subtotal,$line);$lines[]=[$product,$item,$line];}$discount=(string)($data['discount']??'0');$delivery=(string)($data['delivery_fee']??'0');$total=Money::add(Money::sub($subtotal,$discount),$delivery);if(bccomp($total,'0.00',2)<0)throw ValidationException::withMessages(['discount'=>'Discount cannot exceed subtotal plus delivery fee.']);$sale=Sale::create(['customer_name'=>$data['customer_name'],'phone'=>$data['phone']??null,'address'=>$data['address']??null,'sale_date'=>$data['sale_date'],'subtotal'=>$subtotal,'discount'=>$discount,'delivery_fee'=>$delivery,'total_amount'=>$total,'payment_method'=>$data['payment_method'],'payment_status'=>$data['payment_status'],'user_id'=>$userId]);foreach($lines as [$product,$item,$line]){$sale->items()->create(['product_id'=>$product->id,'quantity'=>$item['quantity'],'selling_price'=>$item['selling_price'],'line_total'=>$line]);$product->update(['stock_quantity'=>bcsub($product->stock_quantity,(string)$item['quantity'],3)]);}$year=date('Y',strtotime($data['sale_date']));$sequence=Invoice::whereYear('invoice_date',$year)->lockForUpdate()->count()+1;Invoice::create(['sale_id'=>$sale->id,'invoice_number'=>sprintf('INV-%d-%04d',$year,$sequence),'invoice_date'=>$data['sale_date']]);return $sale->load('items.product','invoice');});} }